"""Graphical User Interface (GUI) application for sample collection using Draw Folium plugin and drone images

   The image projection is based on EXIF metadata tags information and auxiliaries information such as flight height, course angle and dimension of sensor"""


# --------------------------
#        Imports
# --------------------------
import PySimpleGUI as sg
import os
import sys
import PIL.Image
import io
import base64
import json
from decimal import Decimal, InvalidOperation
import geopandas as gpd
from load_map_tool import create_map
from time import sleep
from threading import Thread

theme='DarkTeal6' #'DarkTeal12'
sg.theme(theme)   # Add a little color to your windows
sg.set_options(font=("Ubuntu", 14, 'bold'))

use_custom_titlebar = False
title_name = 'HARMONIZE Get Samples Tool based on Drone Images'


# Get screen size
width, height = sg.Window.get_screen_size()
height = int(height * 0.96)
width = int(width * 0.99)

#default image at application starting - base64 bytes string
filename = b''


# --------------------------
#        Functions
# --------------------------
def is_decimal(s):
    try:
        Decimal(s)
        return True
    except InvalidOperation:
        return False


def popup(message):
    sg.theme('DarkGrey')
    layout = [[sg.Text(message)]]
    window_popup = sg.Window('', layout, no_titlebar=True, keep_on_top=True, finalize=True)
    return window_popup


def to_shp(file_in):
    """Converts file to ESRI shapefile format using Geopandas"""
    success = False
    try:
        gpd_df = gpd.read_file(file_in)
        if gpd_df.empty:
            print("The file saved is empty, it will be deleted!")
            os.remove(file_in)
        else:
            for geomtype in gpd_df.geom_type.unique():
                 f_out = os.path.splitext(file_in)[0]+'_'+geomtype+'.shp'
                 gpd_df[gpd_df.geom_type == geomtype].to_file(f_out, driver='ESRI Shapefile', layer=geomtype)
            success = True
    except Exception as err:
        print(err)
        print('Stop background task for file:',file_in)
        sys.exit() #stop thread

    return success


# long-running background task
def background_task(target_file):
    # run forever
    while True:
        if os.path.exists(target_file):
                success = to_shp(target_file)
                if success:
                    print('Stop background task for file:',target_file)
                    break
        # block for a while
        sleep(5)


def isTreadAlive():
  for t in threads_monitor:
    if t.is_alive():
      return True
  return False


# Adapted from https://pyquestions.com/python-finding-the-user-s-downloads-folder
def get_download_path():
    """Returns the default downloads path for linux or windows"""
    if os.name == 'nt':
        import winreg
        sub_key = r"Software\Microsoft\Windows\CurrentVersion\Explorer\Shell Folders"
        downloads_guid = "{374DE290-123F-4565-9164-39C4925E467B}"
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, sub_key) as key:
            location = winreg.QueryValueEx(key, downloads_guid)[0]
        return location
    else:
        return os.path.join(os.path.expanduser('~'),'Downloads')


# Adapted from PySimpleGUI.org
def convert_to_bytes(file_or_bytes, resize=None):
    '''
    Will convert into bytes and optionally resize an image that is a file or a base64 bytes object.
    Turns into  PNG format in the process so that can be displayed by tkinter
    :param file_or_bytes: either a string filename or a bytes base64 image object
    :type file_or_bytes:  (Union[str, bytes])
    :param resize:  optional new size
    :type resize: (Tuple[int, int] or None)
    :return: (bytes) a byte-string object
    :rtype: (bytes)
    '''
    if isinstance(file_or_bytes, str):
        img = PIL.Image.open(file_or_bytes)
    else:
        try:
            img = PIL.Image.open(io.BytesIO(base64.b64decode(file_or_bytes)))
        except Exception as e:
            dataBytesIO = io.BytesIO(file_or_bytes)
            img = PIL.Image.open(dataBytesIO)
    
    if img._getexif() == None and isinstance(file_or_bytes, str):
        print('The image has no EXIF information:\n'+file_or_bytes)
        return None

    if resize:
        w,h = img.size
        w = width if w > width else w
        h = height if h > height else h
        img.thumbnail((int(w*0.7),int(h*0.7))) #scale image keeping aspect ratio
    with io.BytesIO() as bio:
        img.save(bio, format="PNG")
        del img
        return bio.getvalue()
    
    
def load_map_tool(file_in):
    root_path = os.path.dirname(file_in)
    fname_json = os.path.join(root_path,'info.json')
    if os.path.exists(fname_json):
        with open(fname_json,'r') as f_json:
                flight_info = json.load(f_json)     
    else:
        flight_info_form = [[sg.Frame('Flight auxiliaries information',
                                    [[sg.Text('Flight height (meters):', size=(23, 1)), sg.InputText(key='-f_height-')],
                                              [sg.Text('Course angle (degrees):', size=(23, 1)), sg.InputText(key='-f_course_angle-')],
                                              [sg.Text('Sensor width (millimeters):', size=(23, 1)), sg.InputText(key='-s_size_w-')],
                                              [sg.Button('OK'), sg.Button('Cancel')]], pad=(0,0))]]
        
        window_form = sg.Window('Flight information form', flight_info_form, finalize=True, keep_on_top=True)
        while True:
            event_form, values_form = window_form.read()
            if event_form == "Exit" or event_form == sg.WIN_CLOSED or event_form == 'Cancel':
                break
            elif event_form == 'OK':
                if is_decimal(values_form['-f_height-']) and is_decimal(values_form['-f_course_angle-']) and is_decimal(values_form['-s_size_w-']):
                    flight_info = {'flight_height_m':float(values_form['-f_height-']),
                                   'course_angle_degrees':float(values_form['-f_course_angle-']),
                                   'sensor_width_mm':float(values_form['-s_size_w-'])}
                    
                    ch = sg.popup_yes_no("Do you want to save this auxiliary information for all images in this folder?", keep_on_top=True, title="Ask confirmation")
                    if ch == 'Yes':
                          with open(fname_json, 'w') as outfile:
                               outfile.write(json.dumps(flight_info, indent=4))
                    break
                else:
                    sg.popup_auto_close('Please, fill the information required!')

        window_form.close()

    if 'flight_info' in locals():
        popup_win = popup("Launching the map application to get samples, please wait...")
        popup_win.refresh()
        popup_win.force_focus()
        samples_file_output = create_map(file_in,flight_info) #Launch the map application to get samples
        popup_win.close()
        sg.popup_auto_close("The application has been successfully launched in your default browser!", keep_on_top=True, title='Information')
        sg.theme(theme)
       
        # Monitoring until the file with samples is saved:
        target_file = os.path.join(get_download_path(),samples_file_output)
        print('Starting background task...')
        daemon = Thread(target=background_task, args=(target_file,), daemon=True, name='Monitor')
        threads_monitor.append(daemon)
        daemon.start()

    
 
# --------------------------
#          Main
# --------------------------

# First the window layout
title = sg.Titlebar(title=title_name, icon=sg.EMOJI_BASE64_HAPPY_IDEA, font=('Courier New', 20, 'bold'))

lin1 = sg.Frame('Choose the folder image:', [[sg.In(enable_events=True, key="-FOLDER-",expand_x=True,expand_y=True),
        sg.FolderBrowse()]],pad=(0,0), expand_x=True,expand_y=False)

file_list_column = sg.Frame('List of Images:',[[sg.Listbox(values=[], enable_events=True, size=(40, 20), key="-FILE LIST-",
                                                            expand_x=True,expand_y=True)]
                                               ],pad=(0,0), expand_x=True,expand_y=True)

# Show the image of the file that was chosen
image_viewer_column = sg.Frame("Choose an image from the list to preview:",
                               [[sg.Push(),sg.Text(key='-TOUT-'),sg.Push()],
                                [sg.Image(convert_to_bytes(filename, resize=True),key="-IMAGE-",expand_x=True,expand_y=True)],
                                 [sg.Button('Load image to get samples',key='-LOAD IMAGE-')]],pad=(0,0), expand_x=True,expand_y=True, element_justification='c')


# ----- Full layout -----
layout = [[lin1],
          [file_list_column,image_viewer_column]
        ]

# --------------------------------- Create Window ---------------------------------
window = sg.Window(title_name, layout, finalize=True, size=(width,height), location=(0,0),
                   right_click_menu=sg.MENU_RIGHT_CLICK_EDITME_VER_EXIT, keep_on_top=True, use_custom_titlebar=use_custom_titlebar,
                   enable_close_attempted_event=True, grab_anywhere=True)

global threads_monitor
threads_monitor = []

# --------------------------------- Event Loop ---------------------------------
while True:    
    event, values = window.read()
    if event in ("Exit","-WINDOW CLOSE ATTEMPTED-"):
        if isTreadAlive():
            ch = sg.popup_yes_no("Do you want to exit the application without saving file with samples?", keep_on_top=True, title="Ask confirmation")
            if ch == 'Yes':
                break
            else:
                window.write_event_value('None','None')
        else:
            break

    # Folder name was filled in, make a list of files in the folder
    if event == "-FOLDER-":
        folder = values["-FOLDER-"]
        try:
            file_list = os.listdir(folder)         # get list of files in folder
        except:
            file_list = []

        if len(file_list) > 0:
            fnames = [f for f in file_list if os.path.isfile(
                os.path.join(folder, f)) and f.lower().endswith((".png", ".jpg", "jpeg", ".tiff", ".bmp"))]
            fnames.sort() #sort before update
            window['-FILE LIST-'].update(fnames)
    elif event == '-FILE LIST-':    # A file was chosen from the listbox
        try:
            filename = os.path.join(values['-FOLDER-'], values['-FILE LIST-'][0])
            window['-TOUT-'].update(os.path.basename(filename))
            window['-IMAGE-'].update(data=convert_to_bytes(filename, resize=True))
        except Exception as E:
            print(f'** Error {E} **')
            pass        # something weird happened making the full filename
    elif event == '-LOAD IMAGE-':    # load image to get sample tool map
        if isinstance(filename, str):
            load_map_tool(filename)

# --------------------------------- Close & Exit ---------------------------------
window.close()